using System.ComponentModel.DataAnnotations;
using System.Reflection;
using System.Text.Json.Serialization.Metadata;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.OpenApi;
using Microsoft.OpenApi;

namespace Odyssey.Api.ApiDocs;

/// <summary>
/// The OpenAPI document, generated by the built-in <c>Microsoft.AspNetCore.OpenApi</c> generator (issue #569; it
/// replaced Swashbuckle). Registration only — which routes serve it, and to whom, is decided in <c>Program.cs</c>.
/// </summary>
public static class OpenApiDocumentRegistration
{
    public const string DocumentName = "v1";

    internal const string AntiforgeryScheme = "antiforgery";

    internal const string CookieScheme = "cookie";

    // Identity's default application cookie name: ".AspNetCore." + IdentityConstants.ApplicationScheme.
    internal const string IdentityCookieName = ".AspNetCore.Identity.Application";

    // Must match the AddAntiforgery header name configured in Program.cs.
    internal const string AntiforgeryHeaderName = "X-XSRF-TOKEN";

    internal const string PersistenceTypeMessage =
        " is a persistence entity type and must not appear in the OpenAPI document. Bind the API contract to " +
        "the matching Odyssey.Dtos type and cast across the boundary explicitly (issue #392).";

    // Type names that more than one contract-carrying Odyssey namespace defines — Sex
    // (Odyssey.Dtos.Application and the Odyssey.Dtos root) today. Component names are keyed on the short type
    // name, so any such collision would give two schemas one name. Computed by scanning the referenced Odyssey
    // assemblies rather than a hand-kept list, so a new module or a newly duplicated name can't silently
    // reintroduce the collision. Groups on FullName, not assembly.
    private static readonly HashSet<string> AmbiguousTypeNames = ContractAssemblies()
        .SelectMany(assembly => assembly.GetExportedTypes())
        .GroupBy(type => type.Name, StringComparer.Ordinal)
        .Where(group => group.Select(type => type.FullName).Distinct(StringComparer.Ordinal).Count() > 1)
        .Select(group => group.Key)
        .ToHashSet(StringComparer.Ordinal);

    public static WebApplicationBuilder AddOpenApiDocument(this WebApplicationBuilder builder)
    {
        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddOpenApi(DocumentName, options =>
        {
            options.OpenApiVersion = OpenApiSpecVersion.OpenApi3_1;
            options.CreateSchemaReferenceId = SchemaReferenceId;
            options.AddDocumentTransformer((document, _, _) =>
            {
                Describe(document);
                return Task.CompletedTask;
            });
            options.AddOperationTransformer((operation, context, _) =>
            {
                MarkRequiredQueryParameters(operation, context);
                KeepOnlyDeclaredRequestContentTypes(operation, context);
                return Task.CompletedTask;
            });
        });

        return builder;
    }

    /// <summary>
    /// The component name for a type, in order: the persistence guard (first, so an entity can never be inlined
    /// to escape it), the module prefix for an ambiguous short name, the Swashbuckle-compatible name for a
    /// closed generic, and otherwise the generator's own default — which inlines primitives and collections.
    /// </summary>
    internal static string? SchemaReferenceId(JsonTypeInfo typeInfo)
    {
        // A nullable value type (Sex?) arrives as Nullable<Sex>; it names the same component as Sex.
        var type = Nullable.GetUnderlyingType(typeInfo.Type) ?? typeInfo.Type;
        if (IsPersistenceType(type))
        {
            throw new InvalidOperationException(type.FullName + PersistenceTypeMessage);
        }

        var defaultId = OpenApiOptions.CreateDefaultSchemaReferenceId(typeInfo);
        if (defaultId is null)
        {
            return null;
        }

        var id = type.IsGenericType && !type.IsGenericTypeDefinition
            ? GenericName(type)
            : defaultId;

        return AmbiguousTypeNames.Contains(type.Name) ? ModulePrefix(type) + id : id;
    }

    // Swashbuckle named a closed generic by its type arguments followed by its own name (PagedResult<ExistingAccount>
    // → ExistingAccountPagedResult); the built-in default is PagedResultOfExistingAccount. Keeping the old shape keeps
    // every published component name stable across the generator change.
    private static string GenericName(Type type)
    {
        var name = type.Name[..type.Name.IndexOf('`', StringComparison.Ordinal)];
        return string.Concat(type.GetGenericArguments().Select(ArgumentName)) + name;
    }

    private static string ArgumentName(Type type) =>
        type.IsGenericType && Nullable.GetUnderlyingType(type) is null
            ? GenericName(type)
            : (Nullable.GetUnderlyingType(type) ?? type).Name;

    /// <summary>
    /// A <c>[Required]</c> (or <c>[BindRequired]</c>) property of a <c>[FromQuery]</c> model is a required query
    /// parameter, and model validation answers <c>400</c> without it. The built-in generator states those as
    /// optional; Swashbuckle stated them as required, and the document must keep saying what the API enforces.
    /// </summary>
    private static void MarkRequiredQueryParameters(OpenApiOperation operation, OpenApiOperationTransformerContext context)
    {
        if (operation.Parameters is null)
        {
            return;
        }

        var required = context.Description.ParameterDescriptions
            .Where(parameter => parameter.Source == BindingSource.Query
                && parameter.ModelMetadata is { } metadata
                && (metadata.IsBindingRequired || metadata.ValidatorMetadata.OfType<RequiredAttribute>().Any()))
            .Select(parameter => parameter.Name)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        foreach (var parameter in operation.Parameters.OfType<OpenApiParameter>())
        {
            if (parameter.In == ParameterLocation.Query && parameter.Name is { } name && required.Contains(name))
            {
                parameter.Required = true;
            }
        }
    }

    /// <summary>
    /// An action restricted by <c>[Consumes]</c> accepts only the types it declares — any other answers 415 — but
    /// the generator lists every type its input formatter could read (<c>application/*+json</c> beside
    /// <c>application/json</c>). The document must not advertise a body the API refuses.
    /// </summary>
    private static void KeepOnlyDeclaredRequestContentTypes(OpenApiOperation operation, OpenApiOperationTransformerContext context)
    {
        var declared = context.Description.ActionDescriptor.EndpointMetadata
            .OfType<ConsumesAttribute>()
            .SelectMany(consumes => consumes.ContentTypes)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        if (declared.Count == 0 || operation.RequestBody?.Content is not { } content)
        {
            return;
        }

        foreach (var contentType in content.Keys.Where(key => !declared.Contains(key)).ToList())
        {
            content.Remove(contentType);
        }
    }

    private static void Describe(OpenApiDocument document)
    {
        document.Info = new OpenApiInfo { Title = "Odyssey API", Version = DocumentName };

        // The generator fills servers from the request's Host header, so a reflected value would end up in the
        // document and Scalar would send "try it" there (issue #569 §7.4). Scalar derives the server from its
        // own page instead.
        document.Servers = [];

        document.Components ??= new OpenApiComponents();
        document.Components.SecuritySchemes ??= new Dictionary<string, IOpenApiSecurityScheme>(StringComparer.Ordinal);

        // The Identity application cookie, the only scheme the API accepts since issue #245 removed the bearer
        // handler. Advertising a bearer scheme here would promise a token login that /login now refuses.
        document.Components.SecuritySchemes[CookieScheme] = new OpenApiSecurityScheme
        {
            Type = SecuritySchemeType.ApiKey,
            Name = IdentityCookieName,
            In = ParameterLocation.Cookie,
            Description = "The session cookie POST /login?useCookies=true sets. Bearer tokens are not supported.",
        };

        // Every write is additionally gated on the antiforgery header (enforced in Program.cs). Advertising only
        // an authentication scheme left "try it" on any POST/PUT/DELETE failing with a bare 400 (issue #382).
        document.Components.SecuritySchemes[AntiforgeryScheme] = new OpenApiSecurityScheme
        {
            Type = SecuritySchemeType.ApiKey,
            Name = AntiforgeryHeaderName,
            In = ParameterLocation.Header,
            Description =
                "Antiforgery token for cookie-authenticated writes. GET /api/antiforgery/token " +
                "returns the value (and sets the paired cookie); echo it here to exercise any " +
                "POST/PUT/PATCH/DELETE endpoint.",
        };

        document.Security =
        [
            new OpenApiSecurityRequirement
            {
                [new OpenApiSecuritySchemeReference(CookieScheme, document)] = [],
                [new OpenApiSecuritySchemeReference(AntiforgeryScheme, document)] = [],
            },
        ];
    }

    // The *.Context assemblies are excluded on purpose (issue #392). Most finance enums are defined twice —
    // once in Odyssey.Dtos as the API contract, once in Odyssey.Context as the stored column type — but only
    // the Dtos copy is ever meant to reach the OpenAPI surface, so the entity copy is not a collision to
    // disambiguate. An entity type that does reach the surface is the defect, which IsPersistenceType rejects.
    private static IEnumerable<Assembly> ContractAssemblies()
    {
        var api = typeof(OpenApiDocumentRegistration).Assembly;
        return api.GetReferencedAssemblies()
            .Where(name => name.Name?.StartsWith("Odyssey.", StringComparison.Ordinal) == true)
            .Select(Assembly.Load)
            .Prepend(api)
            .Where(assembly => !IsPersistenceAssembly(assembly));
    }

    private static bool IsPersistenceAssembly(Assembly assembly) =>
        assembly.GetName().Name is { } name
        && name.StartsWith("Odyssey.", StringComparison.Ordinal)
        && name.EndsWith(".Context", StringComparison.Ordinal);

    private static bool IsPersistenceType(Type type) => IsPersistenceAssembly(type.Assembly);

    // The module segment of a DTO namespace: "Odyssey.Dtos.Finance" → "Finance". The project's own root is
    // labelled "Shared" rather than "Dtos" — the label names the type's *role* (it crosses modules), so the
    // disambiguated ids are ApplicationSex / SharedSex. A type outside the DTO project keeps the whole namespace
    // tail. These are list patterns over the split namespace, so a rename of the DTO project does NOT reach them
    // by search-and-replace; OpenApiSchemaIdTests pins the resulting ids, which is what catches that.
    private static string ModulePrefix(Type type)
    {
        var segments = (type.Namespace ?? string.Empty).Split('.');
        return segments switch
        {
            ["Odyssey", "Dtos"] => "Shared",
            ["Odyssey", "Dtos", var module, ..] => module,
            ["Odyssey", .. var tail] => string.Concat(tail),
            _ => string.Empty,
        };
    }
}
